const dynamicTranslate = (text, language) => {
  if (language === "English") return text;
  const dict = makeLookup(language);
  if (dict[text]) return dict[text];
  let voice = text.match(/^Female voice • (Ready|Browser voice)$/);
  if (voice) return language === "Hindi" ? `महिला आवाज़ • ${voice[1] === "Ready" ? "तैयार" : "ब्राउज़र आवाज़"}` : `महिला आवाज • ${voice[1] === "Ready" ? "तयार" : "ब्राउझर आवाज"}`;
  let m = text.match(/^(\d+) active$/); if (m) return language === "Hindi" ? `${m[1]} सक्रिय` : `${m[1]} सक्रिय`;
  m = text.match(/^(\d+) readings saved$/); if (m) return language === "Hindi" ? `${m[1]} रीडिंग्स सेव की गईं` : `${m[1]} नोंदी जतन केल्या`;
  m = text.match(/^Resend available in (\d+)s$/); if (m) return language === "Hindi" ? `${m[1]} सेकंड में फिर उपलब्ध` : `${m[1]} सेकंदांनी पुन्हा उपलब्ध`;
  m = text.match(/^Wait (\d+)s$/); if (m) return language === "Hindi" ? `${m[1]} सेकंड प्रतीक्षा करें` : `${m[1]} सेकंद थांबा`;
  m = text.match(/^Selected: (.+)$/); if (m) return language === "Hindi" ? `चयनित: ${m[1]}` : `निवडलेले: ${m[1]}`;
  m = text.match(/^(\d+) reports? in your account\.?$/); if (m) return language === "Hindi" ? `${m[1]} रिपोर्ट आपके खाते में हैं।` : `तुमच्या खात्यात ${m[1]} अहवाल आहेत.`;
  m = text.match(/^Responding in (English|Hindi|Marathi)\. Ask in English, Hindi or Marathi\.$/); if (m) return language === "Hindi" ? `जवाब ${m[1] === "Hindi" ? "हिंदी" : m[1] === "Marathi" ? "मराठी" : "अंग्रेज़ी"} में दिया जा रहा है। अंग्रेज़ी, हिंदी या मराठी में पूछें।` : `उत्तर ${m[1] === "Marathi" ? "मराठीत" : m[1] === "Hindi" ? "हिंदीत" : "इंग्रजीत"} दिले जात आहे. इंग्रजी, हिंदी किंवा मराठीत विचारा.`;
  m = text.match(/^Generated (.+) plan$/); if (m) return language === "Hindi" ? `${m[1]} योजना तैयार की गई` : `${m[1]} योजना तयार केली`;
  return dict[text] || text;
};

const originalTextNodes = new WeakMap();
const originalAttrs = new WeakMap();
const ATTRS = ["placeholder", "title", "aria-label", "aria-description"];

export function translateDocument(language = getLanguage()) {
  if (typeof document === "undefined") return;
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  let node;
  while ((node = walker.nextNode())) {
    const parent = node.parentElement;
    if (!parent || ["SCRIPT", "STYLE", "NOSCRIPT"].includes(parent.tagName)) continue;
    if (!originalTextNodes.has(node)) {
      originalTextNodes.set(node, node.nodeValue);
    }
    const original = originalTextNodes.get(node);
    const leading = original.match(/^\s*/)?.[0] || "";
    const trailing = original.match(/\s*$/)?.[0] || "";
    const core = original.trim();
    if (!core) continue;
    const translated = dynamicTranslate(core, language);
    const nextValue = leading + translated + trailing;
    if (node.nodeValue !== nextValue) node.nodeValue = nextValue;
  }
  document.querySelectorAll("input,textarea,select,button,[aria-label],[title]").forEach(el => {
    ATTRS.forEach(attr => {
      if (!el.hasAttribute(attr)) return;
      let attrs = originalAttrs.get(el);
      if (!attrs) { attrs = {}; originalAttrs.set(el, attrs); }
      if (!(attr in attrs)) attrs[attr] = el.getAttribute(attr);
      const original = attrs[attr];
      if (original) { const next = dynamicTranslate(original, language); if (el.getAttribute(attr) !== next) el.setAttribute(attr, next); }
    });
  });
  document.documentElement.lang = language === "Hindi" ? "hi" : language === "Marathi" ? "mr" : "en";
}

export function installDocumentTranslator(language = getLanguage()) {
  if (typeof document === "undefined") return () => {};
  let current = language;
  const run = () => translateDocument(current);
  run();
  const observer = new MutationObserver(() => {
    // React frequently replaces text nodes. The WeakMap keeps their original
    // English value so switching Hindi <-> Marathi always works correctly.
    run();
  });
  observer.observe(document.body, { childList: true, subtree: true, characterData: true, attributes: true, attributeFilter: ATTRS });
  const onLang = e => { current = e.detail || getLanguage(); run(); };
  window.addEventListener("hg-language-change", onLang);
  return () => { observer.disconnect(); window.removeEventListener("hg-language-change", onLang); };
}

export function getLanguage() { return localStorage.getItem("hg_language") || "English"; }
export function setLanguage(language) {
  localStorage.setItem("hg_language", language);
  window.dispatchEvent(new CustomEvent("hg-language-change", { detail: language }));
}
export function t(language, key) { return translations[language]?.[key] ?? translations.English[key] ?? key; }
export const languageOptions = [["English", "English"], ["Hindi", "हिंदी"], ["Marathi", "मराठी"]];
